===== PayoutCap.java
/**
 * The most the MHPCO will pay out over the life of a policy: twice the
 * insurance sum of the items it covers.
 *
 * This is the one place that decides the office's payout ceiling. It is a
 * separate decision from what the covered items are insured for: the MHPCO may
 * revalue the items it covers without changing how far it will go beyond that
 * value, and may change how far it will go without revaluing anything.
 */
public final class PayoutCap {

    private static final int CAP_MULTIPLE_OF_INSURANCE_SUM = 2;

    private PayoutCap() {
    }

    public static int overInsuranceSum(int insuranceSumInG) {
        return CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumInG;
    }
}
===== Policy.java
import java.util.List;

/**
 * A policy the MHPCO has issued over a list of insured items: what the office
 * covers, and what the covered items are insured for.
 *
 * How far beyond the insurance sum the office will pay out is a separate
 * decision, made by {@link PayoutCap}.
 */
public final class Policy {

    private final List<Item> insuredItems;

    public Policy(List<Item> insuredItems) {
        this.insuredItems = List.copyOf(insuredItems);
    }

    /**
     * What the covered items are insured for, all together: each item at its
     * own insurance value, summed. What the MHPCO charged to insure them does
     * not enter into it -- neither a risk surcharge nor the component block
     * offer moves the insurance sum.
     */
    public int insuranceSum() {
        return insuredItems.stream()
                .mapToInt(InsuranceValues::insuranceValueOf)
                .sum();
    }

    /**
     * The most the MHPCO will pay out over the life of this policy. No claim
     * has yet been made against a policy, so this is the whole cap; what
     * remains of it after claims is a claim's concern.
     */
    public int cap() {
        return PayoutCap.overInsuranceSum(insuranceSum());
    }

    /**
     * The MHPCO settles an incident against this policy: it reimburses the
     * incident and reports what the settlement leaves of the policy's cap.
     */
    public Claim claim(Incident incident) {
        int payout = Reimbursement.forIncident(incident, this::damagedItem);
        return new Claim(payout, cap() - payout);
    }

    /**
     * The insured item a reported damage was suffered by, found among the
     * items this policy covers.
     */
    private Item damagedItem(Damage damage) {
        return insuredItems.stream()
                .filter(item -> item.type().equals(damage.itemType()))
                .findFirst()
                .orElseThrow();
    }
}
===== Reimbursement.java
import java.math.BigDecimal;

/**
 * What the MHPCO reimburses for reported damage: the amount it reimburses for
 * the damage, less the deductible that applies per damage event.
 *
 * This is the one place that says how much an incident is worth to the
 * claimant. How far the MHPCO will actually go in paying that -- what the
 * policy's cap leaves of it -- is a separate decision, made where the policy
 * settles the claim.
 */
public final class Reimbursement {

    private static final int DEDUCTIBLE_PER_DAMAGE_IN_G = 100;

    private static final int HIGH_ENCHANTMENT_LEVEL = 8;

    private static final int HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;

    private Reimbursement() {
    }

    /**
     * An incident is reimbursed damage by damage: the office settles each
     * reported damage on its own and pays the sum, because the deductible is
     * charged per damage event rather than once for the incident.
     *
     * The MHPCO keeps intermediate amounts as fractions and rounds only the
     * final payout, so each damage is settled as a fraction and the sum is
     * narrowed to whole G once, here. No active example yields a fractional
     * payout, so that narrowing is exact today; how the office rounds one
     * that is not -- in its own favour, down -- is a decision no active
     * behaviour has asked for, and this is where it will be made.
     */
    public static int forIncident(Incident incident, Coverage coverage) {
        return incident.damages().stream()
                .map(damage -> forDamage(damage, coverage.damagedIn(damage)))
                .reduce(BigDecimal.ZERO, BigDecimal::add)
                .intValueExact();
    }

    /**
     * One reported damage is settled in two steps the MHPCO decides
     * separately: how much of the damage it reimburses at all, and then the
     * deductible it charges for the damage event.
     */
    private static BigDecimal forDamage(Damage damage, Item damagedItem) {
        return reimbursableAmount(damage, damagedItem)
                .subtract(BigDecimal.valueOf(DEDUCTIBLE_PER_DAMAGE_IN_G));
    }

    /**
     * How much of a reported damage the MHPCO reimburses, before the
     * deductible: damage to a highly enchanted item is reimbursed at half,
     * anything else in full.
     */
    private static BigDecimal reimbursableAmount(Damage damage, Item damagedItem) {
        if (isHighlyEnchanted(damagedItem)) {
            return Percentage.of(damage.amount(), HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT);
        }
        return BigDecimal.valueOf(damage.amount());
    }

    /**
     * The MHPCO only reimburses damage to an item of enchantment level 8 or
     * more at half: such items are too volatile to insure in full.
     */
    private static boolean isHighlyEnchanted(Item item) {
        return item.enchantment() >= HIGH_ENCHANTMENT_LEVEL;
    }
}
===== InsurableItems.java
import java.util.List;

/**
 * The item types the MHPCO insures at all: the main items of its price list
 * and the components it offers. An item of any other type cannot be covered,
 * and the MHPCO declines the whole request rather than quoting around it.
 *
 * This is the one place that decides what the office will take on. What an
 * accepted item is insured for is a separate decision, made by
 * {@link InsuranceValues}.
 */
public final class InsurableItems {

    private InsurableItems() {
    }

    public static boolean isInsurable(String itemType) {
        return MainItemPricing.isMainItem(itemType) || ComponentPricing.isComponent(itemType);
    }

    public static void requireAllInsurable(List<Item> items) {
        items.stream()
                .map(Item::type)
                .filter(itemType -> !isInsurable(itemType))
                .findFirst()
                .ifPresent(itemType -> {
                    throw new IllegalArgumentException(
                            "The MHPCO does not insure items of type " + itemType);
                });
    }
}
===== InsuranceValues.java
/**
 * What the MHPCO insures an item for. Each family of insurable item is valued
 * by the pricing policy that owns it: a main item by the price list, a
 * component by the flat component value.
 *
 * This is the one place that decides which valuation an item falls under. It
 * is a separate decision from whether the MHPCO will cover the item at all:
 * the office may take on a new kind of item without changing what the items it
 * already covers are worth, and may revalue what it covers without widening
 * what it accepts.
 */
public final class InsuranceValues {

    private InsuranceValues() {
    }

    public static int insuranceValueOf(Item item) {
        if (ComponentPricing.isComponent(item.type())) {
            return ComponentPricing.componentInsuranceValue(item);
        }
        return MainItemPricing.mainItemInsuranceValue(item);
    }
}

===== Percentage.java
import java.math.BigDecimal;
import java.math.MathContext;

/**
 * A percentage of an amount in G, as the MHPCO measures every premium
 * modifier: a risk surcharge against an item's base premium, a discount or
 * assessment surcharge against the policy premium.
 *
 * This is the one place that says how the MHPCO turns a modifier percentage
 * into an amount, so a change to that arithmetic is made here and nowhere
 * else.
 */
public final class Percentage {

    private static final BigDecimal WHOLE = BigDecimal.valueOf(100);

    /**
     * The MHPCO keeps intermediate amounts as fractions and rounds only the
     * final premium or payout, so a modifier amount is carried at a precision
     * far beyond the whole G it will finally be rounded to. Stating the
     * precision here keeps a modifier whose share does not divide evenly -- a
     * third-share surcharge, say -- an arithmetic detail rather than a failed
     * quote.
     */
    private static final MathContext KEPT_AS_A_FRACTION = MathContext.DECIMAL64;

    private Percentage() {
    }

    public static BigDecimal of(BigDecimal amountInG, int percent) {
        return amountInG.multiply(BigDecimal.valueOf(percent)).divide(WHOLE, KEPT_AS_A_FRACTION);
    }

    public static BigDecimal of(int amountInG, int percent) {
        return of(BigDecimal.valueOf(amountInG), percent);
    }
}
===== ItemRiskSurcharges.java
import java.math.BigDecimal;
import java.util.List;
import java.util.function.Predicate;

/**
 * The MHPCO's item-specific risk surcharges. A surcharge is charged only for
 * the items that carry the risk, and is measured against that item's own base
 * premium -- never against the policy total.
 */
public final class ItemRiskSurcharges {

    private static final int CURSE_SURCHARGE_PERCENT = 50;

    private static final int HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;

    private static final int HIGH_ENCHANTMENT_LEVEL = 5;

    private ItemRiskSurcharges() {
    }

    /**
     * Every item-specific risk surcharge the MHPCO charges, summed. This is the
     * one place that says which risks are item-specific: a new item risk is
     * added here and nowhere else.
     */
    public static BigDecimal totalItemSurcharges(List<Item> items) {
        return curseSurcharge(items).add(highEnchantmentSurcharge(items));
    }

    /**
     * Cursed items add a 50 % risk surcharge on their own base premium.
     */
    private static BigDecimal curseSurcharge(List<Item> items) {
        return surchargeOnItemsAtRisk(items, Item::cursed, CURSE_SURCHARGE_PERCENT);
    }

    /**
     * Highly enchanted items -- enchantment level 5 or more -- add a 30 % risk
     * surcharge on their own base premium.
     */
    private static BigDecimal highEnchantmentSurcharge(List<Item> items) {
        return surchargeOnItemsAtRisk(
                items, ItemRiskSurcharges::isHighlyEnchanted, HIGH_ENCHANTMENT_SURCHARGE_PERCENT);
    }

    private static boolean isHighlyEnchanted(Item item) {
        return item.enchantment() >= HIGH_ENCHANTMENT_LEVEL;
    }

    /**
     * The MHPCO's scope rule for every item-specific surcharge, decided in one
     * place: only the items carrying the risk are charged, each against its own
     * base premium, and the amounts are summed into the policy premium.
     *
     * Every risk the MHPCO recognises is a property of a main item -- a curse
     * or an enchantment -- so only main items can carry one, and the base
     * premium measured against is the price-list premium of that main item.
     */
    private static BigDecimal surchargeOnItemsAtRisk(
            List<Item> items, Predicate<Item> carriesTheRisk, int surchargePercent) {
        return items.stream()
                .filter(carriesTheRisk)
                .map(item -> Percentage.of(MainItemPricing.mainItemBasePremium(item), surchargePercent))
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}
===== MainItemPricing.java
import java.util.List;
import java.util.Map;

/**
 * The MHPCO price list for main items. Each main item type has one entry on
 * the list, stating both what the office charges to insure such an item and
 * what it insures it for; the entry is independent of how many such items a
 * policy covers.
 */
public final class MainItemPricing {

    /**
     * One line of the MHPCO price list: what insuring such an item costs, and
     * what it is insured for.
     */
    private record PriceListEntry(int basePremiumInG, int insuranceValueInG) {
    }

    private static final Map<String, PriceListEntry> PRICE_LIST = Map.of(
            "sword", new PriceListEntry(100, 1000),
            "amulet", new PriceListEntry(60, 600),
            "staff", new PriceListEntry(80, 800),
            "potion", new PriceListEntry(40, 400));

    private MainItemPricing() {
    }

    public static boolean isMainItem(String itemType) {
        return PRICE_LIST.containsKey(itemType);
    }

    /**
     * The price-list premium the MHPCO charges for one main item. Only main
     * items appear on the price list, so this is defined for main items alone;
     * components are priced by their own MHPCO policy, by the set they belong
     * to rather than one by one.
     */
    public static int mainItemBasePremium(Item item) {
        return entryFor(item).basePremiumInG();
    }

    /**
     * The base premium for every main item in a policy: the MHPCO charges each
     * main item at its price-list premium, with no offer for quantity.
     */
    public static int mainItemsBasePremium(List<Item> items) {
        return items.stream()
                .filter(item -> isMainItem(item.type()))
                .mapToInt(MainItemPricing::mainItemBasePremium)
                .sum();
    }

    /**
     * The insurance value the MHPCO's price list puts on one main item: what
     * the item is insured for, as opposed to what insuring it costs.
     */
    public static int mainItemInsuranceValue(Item item) {
        return entryFor(item).insuranceValueInG();
    }

    private static PriceListEntry entryFor(Item item) {
        return PRICE_LIST.get(item.type());
    }
}
===== ComponentPricing.java
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

/**
 * The MHPCO pricing policy for components: 25 G base premium each, with a
 * building block of exactly 3 alike components offered at 60 G.
 */
public final class ComponentPricing {

    private static final Set<String> COMPONENT_TYPES = Set.of("rune", "moonstone");

    private static final int COMPONENT_BASE_PREMIUM_IN_G = 25;

    private static final int COMPONENT_INSURANCE_VALUE_IN_G = 250;

    private static final int COMPONENTS_PER_BLOCK = 3;

    private static final int BLOCK_BASE_PREMIUM_IN_G = 60;

    private ComponentPricing() {
    }

    public static boolean isComponent(String itemType) {
        return COMPONENT_TYPES.contains(itemType);
    }

    /**
     * The base premium for every component in a policy: components are grouped
     * into sets of alike components, and each set is priced on its own.
     */
    public static int componentsBasePremium(List<Item> items) {
        Map<String, Long> alikeCounts = items.stream()
                .filter(item -> isComponent(item.type()))
                .collect(Collectors.groupingBy(ComponentPricing::alikeGroup, Collectors.counting()));
        return alikeCounts.values().stream()
                .mapToInt(count -> alikeComponentsBasePremium(count.intValue()))
                .sum();
    }

    /**
     * Components are alike when they are of the same item type: a rune and a
     * moonstone are never alike, however rune-y or gemstone-y they look. This
     * is the one place the MHPCO's reading of "alike" is decided.
     */
    private static String alikeGroup(Item item) {
        return item.type();
    }

    private static int alikeComponentsBasePremium(int count) {
        if (formsABlock(count)) {
            return BLOCK_BASE_PREMIUM_IN_G;
        }
        return count * COMPONENT_BASE_PREMIUM_IN_G;
    }

    /**
     * The MHPCO offers the block only for exactly 3 alike components: 4 alike
     * components are not a block plus a spare, and 7 are not two blocks plus a
     * spare -- each of those is charged at the full per-component premium.
     */
    private static boolean formsABlock(int alikeCount) {
        return alikeCount == COMPONENTS_PER_BLOCK;
    }

    /**
     * Every component is insured at 250 G, whatever the MHPCO charges for the
     * set it belongs to: the block offer reduces the premium, not the value.
     */
    public static int componentInsuranceValue(Item item) {
        return COMPONENT_INSURANCE_VALUE_IN_G;
    }
}
===== PolicyWideModifiers.java
import java.math.BigDecimal;

/**
 * The MHPCO's policy-wide premium modifiers. Unlike the item-specific risk
 * surcharges, these are measured against the policy premium as a whole and
 * depend on the customer's history with the MHPCO rather than on any item.
 *
 * This is the one place that says which modifiers are policy-wide: a further
 * policy-wide modifier is added here and nowhere else. So far the MHPCO grants
 * the loyalty discount and charges the initial assessment surcharge.
 */
public final class PolicyWideModifiers {

    private static final int LOYALTY_YEARS = 2;

    private static final int LOYALTY_DISCOUNT_PERCENT = 20;

    private static final int INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;

    private static final int FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;

    private final Customer customer;

    private int contractsIssued;

    public PolicyWideModifiers(Customer customer) {
        this.customer = customer;
    }

    /**
     * The net effect of every policy-wide modifier on a policy premium:
     * positive amounts are charged to the customer, negative amounts are
     * granted to the customer. Each modifier states its own direction, so this
     * sum says only which modifiers the MHPCO applies policy-wide.
     */
    public BigDecimal totalPolicyModifiers(BigDecimal policyPremium) {
        return initialAssessmentSurcharge(policyPremium)
                .add(loyaltyDiscount(policyPremium))
                .add(followUpContractDiscount(policyPremium));
    }

    /**
     * The MHPCO notes that a contract has been issued to this customer. Every
     * later contract is a follow-up contract, which is what the follow-up
     * contract discount is measured against.
     */
    public void recordContractIssued() {
        contractsIssued++;
    }

    /**
     * Customers receive a 15 % discount on each contract after their first.
     */
    private BigDecimal followUpContractDiscount(BigDecimal policyPremium) {
        if (!hasAPreviousContract()) {
            return BigDecimal.ZERO;
        }
        return Percentage.of(policyPremium, FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT).negate();
    }

    private boolean hasAPreviousContract() {
        return contractsIssued > 0;
    }

    /**
     * Long-standing customers -- 2 or more years of business with the MHPCO --
     * receive a 20 % loyalty discount on the policy premium.
     */
    private BigDecimal loyaltyDiscount(BigDecimal policyPremium) {
        if (!isLongStandingCustomer()) {
            return BigDecimal.ZERO;
        }
        return Percentage.of(policyPremium, LOYALTY_DISCOUNT_PERCENT).negate();
    }

    /**
     * The MHPCO counts a customer as long-standing from 2 full years of
     * business onwards; a customer in their second year is still a newcomer.
     */
    private boolean isLongStandingCustomer() {
        return customer.yearsWithMHPCO() >= LOYALTY_YEARS;
    }

    /**
     * Every item in a quote is treated as a first insurance, regardless of the
     * customer's history with the MHPCO, and carries a 10 % initial assessment
     * surcharge on the policy premium.
     */
    private BigDecimal initialAssessmentSurcharge(BigDecimal policyPremium) {
        return Percentage.of(policyPremium, INITIAL_ASSESSMENT_SURCHARGE_PERCENT);
    }

}
